"use strict";(globalThis.webpackChunkkraptor_wiki=globalThis.webpackChunkkraptor_wiki||[]).push([[752],{1879(i){i.exports=JSON.parse('{"tag":{"label":"CloudStream Yard\u0131m","permalink":"/kraptor-wiki/docs/tags/cloud-stream-yardim","allTagsPath":"/kraptor-wiki/docs/tags","count":15,"items":[{"id":"cloudstream-yardim/altyazi","title":"Altyaz\u0131 sorunu","description":"Altyaz\u0131 karakter sorunu \xf6rne\u011fi","permalink":"/kraptor-wiki/docs/cloudstream-yardim/altyazi"},{"id":"Ba\u011flant\u0131lar","title":"Ba\u011flant\u0131lar","description":"Telegram","permalink":"/kraptor-wiki/docs/Ba\u011flant\u0131lar"},{"id":"ayzen-repo/bilgilendirme","title":"Bilgilendirme","description":"Ayzen Repo ByAyzen\'nin baz\u0131 \xf6zel eklentilerini geli\u015ftirmek i\xe7in kurdu\u011fu \xf6zel reponun ismidir.","permalink":"/kraptor-wiki/docs/ayzen-repo/bilgilendirme"},{"id":"cloudstream-pc/cloudstream-pc-kullanim","title":"CloudStream Bilgisayarda Kullan\u0131labilir mi?","description":"CloudStream\'in hen\xfcz resmi bir Windows, Linux veya Mac s\xfcr\xfcm\xfc bulunmamaktad\u0131r. Ancak, Android tabanl\u0131 yap\u0131s\u0131 sayesinde bilgisayar\u0131n\u0131zda farkl\u0131 y\xf6ntemlerle sorunsuz bir \u015fekilde kullanabilirsiniz.","permalink":"/kraptor-wiki/docs/cloudstream-pc/cloudstream-pc-kullanim"},{"id":"cloudstream-yardim/cloudstream","title":"CloudStream nedir?","description":"CloudStream, eklentiler sayesinde internet sitelerini gezip oradan film ve dizi bilgisi getiren bir programd\u0131r. CloudStream\'i bir taray\u0131c\u0131 gibi d\xfc\u015f\xfcnebilirsiniz.","permalink":"/kraptor-wiki/docs/cloudstream-yardim/cloudstream"},{"id":"cloudstream-yardim/cskurulum","title":"Cloudstream nereden ve nas\u0131l indirilir?","description":"Cloudstream a\xe7\u0131k kaynak kodlu bir uygulama olmas\u0131 sebebiyle GitHub \xfczerinden payla\u015f\u0131l\u0131yor. Stabil ve Beta s\xfcr\xfcmlerini GitHub sayfas\u0131ndan indirebilirsiniz.","permalink":"/kraptor-wiki/docs/cloudstream-yardim/cskurulum"},{"id":"cloudstream-yardim/dil_nsfw","title":"Dil ve NSFW sorunlar\u0131","description":"Baz\u0131 Eklentiler uygulama i\xe7erisinde g\xf6z\xfckmeyebilir bu durumu \xe7\xf6zmek i\xe7in a\u015fa\u011f\u0131daki ad\u0131mlar\u0131 takip edin.","permalink":"/kraptor-wiki/docs/cloudstream-yardim/dil_nsfw"},{"id":"cloudstream-yardim/Eklentiler","title":"Eklentiler Nedir?","description":"Eklentiler, CloudStream uygulamas\u0131n\u0131 i\u015flevsel hale getiren temel bile\u015fenlerdir. Uygulaman\u0131n kendisi bir medya oynat\u0131c\u0131 altyap\u0131s\u0131 sunarken, eklentiler bu altyap\u0131y\u0131 web sitelerinden veri kaz\u0131ma (scraping) y\xf6ntemiyle besleyen ba\u011f\u0131ms\u0131z kod par\xe7ac\u0131klar\u0131d\u0131r.","permalink":"/kraptor-wiki/docs/cloudstream-yardim/Eklentiler"},{"id":"ayzen-repo/eklenti-bilgi","title":"Filmbol Eklentisi Bilgilendirme","description":"AyzenCS3 reposunda bulunan Filmbol eklentisi, tamamen \xfccretli olarak indirme ve izleme hizmeti sunmaktad\u0131r.","permalink":"/kraptor-wiki/docs/ayzen-repo/eklenti-bilgi"},{"id":"cloudstream-yardim/Hatalar","title":"Hatalar","description":"- Score Hatas\u0131","permalink":"/kraptor-wiki/docs/cloudstream-yardim/Hatalar"},{"id":"cloudstream-yardim/kaynakkalite","title":"Kaynak ve Kalite Ayarlar\u0131","description":"CloudStream \xfczerinde izleme deneyiminizi \xf6zelle\u015ftirmek i\xe7in kaynaklar\u0131n \xf6ncelik s\u0131ras\u0131n\u0131 belirleyebilir veya istemedi\u011finiz kaliteleri tamamen gizleyebilirsiniz.","permalink":"/kraptor-wiki/docs/cloudstream-yardim/kaynakkalite"},{"id":"hosgeldin","title":"Kraptor\'un CloudStream Wikisine Ho\u015fgeldin!","description":"Bu wiki CloudStream ve ilgili sorunlar i\xe7in k\u0131sa rehberler i\xe7erir. Sol men\xfcden konu se\xe7erek okumaya ba\u015flayabilirsin.","permalink":"/kraptor-wiki/docs/hosgeldin"},{"id":"ayzen-repo/m3uplayer-bilgilendirme","title":"M3UPlayer Eklentisi Bilgilendirme","description":"M3UPlayer eklentisi Cloudstream uygulamas\u0131na M3U veya Xtream listelerini girerek bunlar\u0131 kullanman\u0131z\u0131 sa\u011fl\u0131yor. Eklentiyi indirdi\u011finizde sol tarafta \xe7\u0131kan Ayar butonu arac\u0131l\u0131\u011f\u0131yla listelerinizi girebilir, s\u0131ralama yapabilir, kategorilendirme yapabilir ve daha bir \xe7ok \xf6zelli\u011fi kullanabilirsiniz.","permalink":"/kraptor-wiki/docs/ayzen-repo/m3uplayer-bilgilendirme"},{"id":"cloudstream-yardim/score","title":"Score sistemi nedir?","description":"Cloudstream\'in 4.5.4 s\xfcr\xfcm\xfc ile birlikte i\xe7erik posterlerinin sa\u011f \xfcst\xfcnde bulunan score yani puan sistemi eklendi.","permalink":"/kraptor-wiki/docs/cloudstream-yardim/score"},{"id":"ayzen-repo/torrential","title":"Torrential Eklentisi Bilgilendirme","description":"Torrential, ba\u015flang\u0131\xe7ta Stremio d\xfcnyas\u0131n\u0131n pop\xfcler eklentisi Torrentio\'yu CloudStream\'e ta\u015f\u0131mak amac\u0131yla yola \xe7\u0131km\u0131\u015f bir projedir. Zaman i\xe7erisinde geli\u015ferek b\xfcnyesine Comet deste\u011fini de katm\u0131\u015f ve genel Stremio eklentilerini \xe7al\u0131\u015ft\u0131rabilen daha geni\u015f kapsaml\u0131 bir yap\u0131ya d\xf6n\xfc\u015fm\xfc\u015ft\xfcr.","permalink":"/kraptor-wiki/docs/ayzen-repo/torrential"}],"unlisted":false}}')}}]);